/*
* DS3231 RTC Clock
*
* Wiring:
*   DS3231 VCC -> 5V
*   DS3231 GND -> GND
*   DS3231 SCL -> A5
*   DS3231 SDA -> A4
*   LED anode  -> D13 (via 220Ω resistor)
*
* Reads time and temperature from the DS3231 every second.
* LED on D13 toggles each second as a visual heartbeat.
* Use the interactive sliders on the DS3231 to set the initial time.
*/

#include <Wire.h>
#include <RtcDS3231.h>
#include <LiquidCrystal_I2C.h>

RtcDS3231<TwoWire> Rtc(Wire);
LiquidCrystal_I2C lcd(0x27,16,2);

const int LED_PIN = 13;
bool ledState = false;

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);

  Rtc.Begin();
  lcd.init();
  lcd.backlight();

// Uncomment the next line to set time from compile timestamp:
// Rtc.SetDateTime(RtcDateTime(__DATE__, __TIME__));

  RtcDateTime now = Rtc.GetDateTime();
  if (!now.IsValid()) {
    Serial.println("RTC lost power — setting time from compile date");
    Rtc.SetDateTime(RtcDateTime(__DATE__, __TIME__));
  }

  Serial.println("DS3231 RTC Clock started");
  Serial.println("-----------------------------");
}

void loop() {
  RtcDateTime now = Rtc.GetDateTime();
  lcd.setCursor(0,0);
// Format: HH:MM:SS
  if (now.Hour() < 10) {
    Serial.print("0");
    lcd.print("0");
  }
  Serial.print(now.Hour());
  lcd.print(now.Hour());
  Serial.print(":");
  lcd.print(":");
  if (now.Minute() < 10){
    Serial.print("0");
    lcd.print("0");
  }
  Serial.print(now.Minute());
  lcd.print(now.Minute());
  Serial.print(":");
  lcd.print(":");
  if (now.Second() < 10) {
    Serial.print("0");
    lcd.print("0");
  }
  Serial.print(now.Second());
  lcd.print(now.Second());

// Date: DD/MM/YYYY
  Serial.print("  ");
  if (now.Day() < 10) Serial.print("0");
  Serial.print(now.Day());
  Serial.print("/");
  if (now.Month() < 10) Serial.print("0");
  Serial.print(now.Month());
  Serial.print("/");
  Serial.print(now.Year());

// Temperature
  RtcTemperature temp = Rtc.GetTemperature();
  Serial.print("  ");
  Serial.print(temp.AsFloatDegC(), 1);
  Serial.println("°C");//alt+0176=degree symbol


  lcd.print(" ");
  lcd.print(temp.AsFloatDegC(), 1);
  lcd.println("°C");//alt+0176=degree symbol
//-----------------------------------------------------

// Date: DD/MM/YYYY
  lcd.setCursor(0,1);
  // lcd.print("  ");
  if (now.Day() < 10) lcd.print("0");
  lcd.print(now.Day());
  lcd.print("/");
  if (now.Month() < 10) lcd.print("0");
  lcd.print(now.Month());
  lcd.print("/");
  lcd.print(now.Year());



// Blink LED every second
  ledState = !ledState;
  digitalWrite(LED_PIN, ledState ? HIGH : LOW);

  delay(1000);
}
